statement_equivalence.renewal_group:
    let fixture = HostFixture::new(/*pending_claim*/ false).await?;
    let evaluation = complete(&fixture).await?;
    let original_files = fixture.original_files()?;
    let upstream = fixture.upstream_files()?;
    let renewed = fixture
        .host
        .as_ref()
        .unwrap()
        .fixture_model_material_renewed_evaluation(&evaluation, fixture.at)?;
    let (client, peer) = fixture
        .host
        .as_ref()
        .unwrap()
        .fixture_model_material_commands(Some(renewed), "original", /*pause*/ None)?;
    assert!(matches!(
        client.fixture_read_current_at(fixture.at).await,
        Err(CommandError::Binding(
            "unchanged full original Evaluation in material"
        ))
    ));
    assert!(matches!(
        client.read_current().await,
        Err(CommandError::Unavailable)
    ));
    assert!(close(client, peer)? > 1);
    let (client, peer) = fixture
        .host
        .as_ref()
        .unwrap()
        .fixture_model_material_commands(
            Some(evaluation.clone()),
            "original",
            /*pause*/ None,
        )?;
    assert!(
        client
            .fixture_read_current_at(evaluation.attestation().expires_at)
            .await
            .is_err()
    );
    assert!(matches!(
        client.read_current().await,
        Err(CommandError::Unavailable)
    ));
    assert_eq!(close(client, peer)?, 0);
    assert_eq!(fixture.original_files()?, original_files);
    assert_eq!(fixture.upstream_files()?, upstream);
    assert!(fixture.finish().await?.into_iter().all(|reads| reads > 2));
    Ok(())
}
